ids = ["LY-340","LY-342","LY-344","LY-402","LY-403","LY-404","LY-405","LY-406","LY-407","LY-408","LY-411","LY-413","LY-415","LY-416","LY-417","LY-418","LY-421","LY-423","LY-424","LY-425"]
assert set(ids) == set(P.keys()), (set(ids) ^ set(P.keys()))
for cid in ids:
    d = P[cid]
    out = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)

# verify by exact id list only
n = 0
for cid in ids:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        json.load(f)
    n += 1
assert n == len(ids) == 20, n
cm = sum(1 for c in ids if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in ids if P[c]["trigger"]["reserve_used"])
